const customTableHeaderButtons = (
    <div className="flex flex-wrap items-center" style={{ gap: '2px' }}>
        {canAddStructure ? (
            <button
                type="button"
                className={headerActionBtnClass}
                title="Add Structure"
                onClick={OpenAddStructureModal}
            >
                Add Structure
            </button>
        ) : (
            <button type="button" className={headerActionBtnClass} title="Add Structure" disabled>
                Add Structure
            </button>
        )}
        {canAddActivity ? (
            <button
                type="button"
                className={headerActionBtnClass}
                title="Add Activity"
                onClick={() => addActivity(undefined)}
            >
                Add Activity-Task
            </button>
        ) : (
            <button type="button" className={headerActionBtnClass} disabled>
                Add Activity-Task
            </button>
        )}
        <Restructure
            context="teamPortfolio"
            items={restructureItems}
            selectedItems={restructureSelectedItems}
            adapter={teamPortfolioRestructureAdapter}
            rules={teamPortfolioRules}
            triggerClassName={headerActionBtnClass}
            triggerLabel="Restructure"
            apiRef={restructureApiRef}
            onViewChange={onRestructureViewChange}
            planPreview={restructurePlanPreview}
            onCompleted={(result) => {
                // A failed batch can still have committed some writes — sp-pnp-js v1
                // has no changeset, so the executor reports exactly what SharePoint
                // accepted in `updatedItems`. Reflecting those keeps the grid honest
                // instead of showing a structure that is no longer in SharePoint; the
                // modal stays open with the error, so nothing is hidden.
                const committed = writesFromResult(result?.updatedItems);
                if (!committed.length) return;
                /**
                 * The executed plan already describes the final hierarchy —
                 * parents, resulting types, new PortfolioStructureID /
                 * TaskID, every affected descendant, across the whole
                 * multi-selection. Rebuild the table from it directly; no
                 * restructure logic lives here and no SharePoint reload is
                 * needed to show the correct structure.
                 */
                const writes = committed;
                const baseTree = (copyDtaArray && copyDtaArray.length) ? copyDtaArray : data;
                const tree = applyRestructurePlanToTree(baseTree, writes);
                patchFlatRows(
                    [allMasterTaskDataFlatLoadeViewBackup, allTaskDataFlatLoadeViewBackup],
                    writes
                );
                // Broadcast to keep-alive pages — no GetMasterData.
                notifyRestructureWrites(writes, 'team-portfolio');
                // Only drop the checkbox selection on a clean run: a partial failure
                // leaves the error modal open, and changing the selection would
                // reset it and take the message away before it was read.
                restructureCallBack(tree, !!result?.success, destinationIdsOf(writes));
            }}
